struct ocelot_ops {
	struct net_device * (*port_to_netdev)(struct ocelot *, int);
	int (*netdev_to_port)(struct net_device *);
	int (*reset)(struct ocelot *);
	u16 (*wm_enc)(u16);
	u16 (*wm_dec)(u16);
	void (*wm_stat)(u32, u32 *, u32 *);
	void (*psfp_init)(struct ocelot *);
	int (*psfp_filter_add)(struct ocelot *, int, struct flow_cls_offload *);
	int (*psfp_filter_del)(struct ocelot *, struct flow_cls_offload *);
	int (*psfp_stats_get)(struct ocelot *, struct flow_cls_offload *, struct flow_stats *);
	void (*cut_through_fwd)(struct ocelot *);
	void (*tas_clock_adjust)(struct ocelot *);
	void (*tas_guard_bands_update)(struct ocelot *, int);
	void (*update_stats)(struct ocelot *);
};

